// Generated by AI (UnitTest MCP)
import assert from "node:assert/strict";
import test from "node:test";

import {
  effectiveEmail,
  isReservedAddress,
  refusal,
} from "./commit-identity.mjs";

test("an address in a reserved testing domain is recognised", () => {
  // The exact address that authored 204 real commits before anyone noticed.
  assert.equal(isReservedAddress("sha@example.invalid"), true);
  assert.equal(isReservedAddress("fixture@example.invalid"), true);
  assert.equal(isReservedAddress("adr-guard@example.invalid"), true);
  assert.equal(isReservedAddress("someone@example.com"), true);
  assert.equal(isReservedAddress("someone@example.org"), true);
  assert.equal(isReservedAddress("someone@example.net"), true);
  assert.equal(isReservedAddress("agent@my.test"), true);
  assert.equal(isReservedAddress("agent@localhost"), true);
});

test("a real contributor address is left alone", () => {
  // The guard has to stay quiet on real identities or people learn to bypass it.
  assert.equal(isReservedAddress("lyndonswan@microsoft.com"), false);
  assert.equal(isReservedAddress("someone@github.com"), false);
  // A real domain that merely contains a reserved word is not reserved.
  assert.equal(isReservedAddress("someone@example.co.uk"), false);
  assert.equal(isReservedAddress("someone@invalid-name.com"), false);
  assert.equal(isReservedAddress("someone@testing.org"), false);
});

test("matching is case- and trailing-dot-insensitive", () => {
  // A fully qualified domain ends in a dot, and git does not normalise case.
  assert.equal(isReservedAddress("Sha@Example.INVALID"), true);
  assert.equal(isReservedAddress("sha@example.invalid."), true);
});

test("a malformed or absent address is not reported as reserved", () => {
  // Nothing configured is git's own error to raise, not this guard's.
  assert.equal(isReservedAddress(""), false);
  assert.equal(isReservedAddress("no-at-sign"), false);
  assert.equal(isReservedAddress("trailing@"), false);
  assert.equal(isReservedAddress(undefined), false);
  assert.equal(isReservedAddress(null), false);
});

test("the environment outranks configuration, as it does for git", () => {
  const configured = "lyndonswan@microsoft.com";
  assert.equal(
    effectiveEmail({ GIT_AUTHOR_EMAIL: "sha@example.invalid" }, configured)
      .email,
    "sha@example.invalid",
  );
  assert.equal(
    effectiveEmail({ EMAIL: "sha@example.invalid" }, configured).email,
    "sha@example.invalid",
  );
  assert.equal(effectiveEmail({}, configured).email, configured);
});

test("an address from the environment is not blamed on a config file", () => {
  // Regression: the guard used to report `git config --show-origin`'s file even
  // when the address came from the environment, which names an innocent file
  // and sends the reader editing the wrong thing.
  const fromEnv = effectiveEmail(
    { GIT_AUTHOR_EMAIL: "sha@example.invalid" },
    "real@microsoft.com",
  );
  assert.equal(fromEnv.source, "environment");
  assert.match(fromEnv.origin, /GIT_AUTHOR_EMAIL/);

  const fromConfig = effectiveEmail({}, "sha@example.invalid");
  assert.equal(fromConfig.source, "config");
  assert.equal(fromConfig.origin, null);
});

test("an unset identity reads as absent rather than as an empty address", () => {
  assert.equal(effectiveEmail({}, null), null);
  assert.equal(effectiveEmail({}, "   "), null);
  assert.equal(effectiveEmail({}, undefined), null);
});

test("the refusal names the address, the file, and how to clear it", () => {
  // The message is the whole value of the guard: it fires inside a pre-commit
  // hook, where the reader has no context and needs the fix in front of them.
  const message = refusal(
    "sha@example.invalid",
    "file:C:/Repos/MindLeak/.git/config",
  );
  assert.match(message, /sha@example\.invalid/);
  assert.match(message, /file:C:\/Repos\/MindLeak\/\.git\/config/);
  assert.match(message, /git config --local --unset user\.email/);
  assert.match(message, /RFC 2606/);
});

test("the refusal omits the origin line when git cannot report one", () => {
  const message = refusal("sha@example.invalid", null);
  assert.doesNotMatch(message, /that address is configured in/);
  assert.match(message, /git config --local --unset user\.email/);
});
